const char *TzString(int32_t idx)
{
    if (idx < 0 || (uint32_t)idx >= TzStringCount) {
        return "";
    }
    return (const char *)TzPoolBytes + TzStringOffsets[idx];
}

const char *TzdbVersionString(void)
{
    return RoboTzdbVersionString;
}

const char *TzGeneratorVersion(void)
{
    return "1.13.0";
}
